import 'package:flutter/material.dart'; import 'package:shared_preferences/shared_preferences.dart'; import '../models/azkar_item.dart'; import '../services/notification_service.dart';
class AzkarPage extends StatefulWidget{const AzkarPage({super.key});@override State<AzkarPage> createState()=>_AzkarPageState();}
class _AzkarPageState extends State<AzkarPage>{String selectedCategory='الصباح';String searchText='';List<String> favoriteIds=[];final searchController=TextEditingController();final azkar=[const AzkarItem(id:'m1',category:'الصباح',title:'ذكر الصباح',text:'أصبحنا وأصبح الملك لله، والحمد لله.'),const AzkarItem(id:'m2',category:'الصباح',title:'آية الكرسي',text:'الله لا إله إلا هو الحي القيوم...'),const AzkarItem(id:'e1',category:'المساء',title:'ذكر المساء',text:'أمسينا وأمسى الملك لله، والحمد لله.'),const AzkarItem(id:'e2',category:'المساء',title:'آية الكرسي',text:'الله لا إله إلا هو الحي القيوم...')]; @override void initState(){super.initState();loadFavorites();}@override void dispose(){searchController.dispose();super.dispose();} Future<void> loadFavorites()async{final p=await SharedPreferences.getInstance();setState(()=>favoriteIds=p.getStringList('favorite_azkar')??[]);} Future<void> toggleFavorite(String id)async{setState(()=>favoriteIds.contains(id)?favoriteIds.remove(id):favoriteIds.add(id)); final p=await SharedPreferences.getInstance(); await p.setStringList('favorite_azkar',favoriteIds);} List<AzkarItem> get filteredAzkar=>azkar.where((i){final q=searchText.trim().toLowerCase();return i.category==selectedCategory&&(q.isEmpty||i.title.toLowerCase().contains(q)||i.text.toLowerCase().contains(q));}).toList(); Widget buildCategoryButton(String cat){final sel=selectedCategory==cat;final cs=Theme.of(context).colorScheme;return Expanded(child:FilledButton.tonal(style:FilledButton.styleFrom(backgroundColor:sel?cs.primary:cs.surfaceContainerHighest,foregroundColor:sel?cs.onPrimary:cs.onSurfaceVariant),onPressed:()=>setState(()=>selectedCategory=cat),child:Text(cat)));} @override Widget build(BuildContext context){final items=filteredAzkar;return Padding(padding:const EdgeInsets.all(16),child:Column(children:[Card(child:ListTile(leading:Icon(Icons.notifications_active,color:Theme.of(context).colorScheme.primary),title:const Text('ضبط الإشعارات حسب الفجر والمغرب'),subtitle:const Text('سيتم استخدام موقعك لحساب مواقيت الصلاة'),trailing:const Icon(Icons.refresh),onTap:()async{await NotificationService.scheduleAzkarNotificationsByPrayerTimes();if(!context.mounted)return;ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم ضبط إشعارات الأذكار')));})),const SizedBox(height:12),TextField(controller:searchController,decoration:const InputDecoration(hintText:'ابحث في الأذكار',prefixIcon:Icon(Icons.search),border:OutlineInputBorder()),onChanged:(v)=>setState(()=>searchText=v)),const SizedBox(height:12),Row(children:[buildCategoryButton('الصباح'),const SizedBox(width:10),buildCategoryButton('المساء')]),const SizedBox(height:12),Expanded(child:items.isEmpty?const Center(child:Text('لا توجد نتائج')):ListView.builder(itemCount:items.length,itemBuilder:(c,i){final it=items[i];final fav=favoriteIds.contains(it.id);return Card(child:ListTile(title:Text(it.title,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(it.text,maxLines:2,overflow:TextOverflow.ellipsis),trailing:IconButton(icon:Icon(fav?Icons.favorite:Icons.favorite_border,color:fav?Colors.red:null),onPressed:()=>toggleFavorite(it.id)),onTap:()=>showModalBottomSheet(context:context,showDragHandle:true,builder:(_)=>Directionality(textDirection:TextDirection.rtl,child:Padding(padding:const EdgeInsets.all(20),child:Text(it.text,style:const TextStyle(fontSize:20,height:1.8))))))));}))]));}}
